import React from 'react';

const Carousel3D = ({ movies = [], currentIndex, setCurrentIndex }) => {
  const displayMovies = movies.length > 0 ? movies : [
    { id: 0, title: "Dune 2", poster_path: "" },
    { id: 1, title: "Wicked", poster_path: "" },
    { id: 2, title: "Interstellar", poster_path: "" },
    { id: 3, title: "Avatar", poster_path: "" },
    { id: 4, title: "Joker", poster_path: "" },
  ];

  const total = displayMovies.length;

  const handleNext = () => setCurrentIndex((prev) => (prev + 1) % total);
  const handlePrev = () => setCurrentIndex((prev) => (prev - 1 + total) % total);

  return (
    <div className="relative w-full py-8 flex flex-col items-center justify-center bg-[#fbfbfa] overflow-hidden">
      
      {/* 3D 스테이지 영역 (높이와 패딩을 줄여 불필요한 상하 여백 압축) */}
      <div 
        className="relative w-full max-w-6xl h-[360px] flex items-center justify-center"
        style={{ perspective: '1600px' }}
      >
        {displayMovies.map((movie, index) => {
          let offset = (index - currentIndex + total) % total;
          if (offset > total / 2) offset -= total;

          const translateX = offset * 240;
          const translateZ = -Math.abs(offset) * 70;
          const rotateY = offset * -14;
          const scale = Math.max(1 - Math.abs(offset) * 0.08, 0.8);
          const opacity = Math.abs(offset) > 2.5 ? 0 : 1;

          return (
            <div
              key={movie.id || index}
              onClick={() => setCurrentIndex(index)}
              style={{
                transform: `translateX(${translateX}px) translateZ(${translateZ}px) rotateY(${rotateY}deg) scale(${scale})`,
                zIndex: total - Math.abs(offset),
                opacity: opacity,
                pointerEvents: opacity === 0 ? 'none' : 'auto',
                transition: 'all 0.5s cubic-bezier(0.25, 1, 0.5, 1)',
              }}
              /* 💡 object-contain을 사용하여 포스터 글씨가 잘리지 않고 전체가 다 보이도록 수정 */
              className={`absolute w-52 h-72 rounded-none overflow-hidden cursor-pointer shadow-xl border flex flex-col bg-white ${
                offset === 0 
                  ? 'border-[#503396] shadow-[0_15px_30px_rgba(80,51,150,0.25)] ring-2 ring-[#503396]/20' 
                  : 'border-zinc-200 brightness-90'
              }`}
            >
              {/* 티켓 상단 영역 */}
              <div className="bg-zinc-100 px-3 py-2 border-b border-dashed border-zinc-300 flex justify-between items-center text-[11px] text-zinc-800 font-black">
                <span className="text-[#503396]">TICKET PASS</span>
                <span className="text-zinc-900">NO. 0{index + 1}</span>
              </div>

              {/* 포스터 이미지 영역 (object-contain으로 변경하여 잘림 방지) */}
              <div className="relative flex-1 overflow-hidden bg-zinc-900 flex items-center justify-center">
                {movie.poster_path ? (
                  <img 
                    src={`https://image.tmdb.org/t/p/w500${movie.poster_path}`} 
                    alt={movie.title || 'Movie Poster'} 
                    className="w-full h-full object-contain pointer-events-none" 
                  />
                ) : (
                  <div className="w-full h-full flex flex-col items-center justify-center text-xs text-zinc-200 p-2 text-center font-bold">
                    <span className="mb-1">{movie.title}</span>
                    <span>MOVIE TICKET</span>
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>

      {/* 네비게이션 버튼 (여백을 줄이기 위해 mt를 줄임) */}
      <div className="flex items-center gap-6 mt-2 z-20">
        <button 
          onClick={handlePrev} 
          className="w-9 h-9 rounded-full bg-white text-zinc-800 border border-zinc-300 flex items-center justify-center hover:bg-zinc-100 transition cursor-pointer font-bold shadow-sm text-sm"
        >
          &larr;
        </button>
        <div className="flex gap-2">
          {displayMovies.map((_, idx) => (
            <span 
              key={idx}
              onClick={() => setCurrentIndex(idx)}
              className={`h-1.5 rounded-full cursor-pointer transition-all ${
                idx === currentIndex ? 'bg-[#503396] w-6' : 'bg-zinc-300 w-1.5'
              }`}
            />
          ))}
        </div>
        <button 
          onClick={handleNext} 
          className="w-9 h-9 rounded-full bg-white text-zinc-800 border border-zinc-300 flex items-center justify-center hover:bg-zinc-100 transition cursor-pointer font-bold shadow-sm text-sm"
        >
          &rarr;
        </button>
      </div>

    </div>
  );
};

export default Carousel3D;
